<div class="toolbar"><p>Los secretos permanecen cifrados hasta que los revelas.</p><a class="btn" href="{{route('credentials.create')}}">+ Nueva credencial</a></div><div class="panel table">@forelse($credentials as $c)<div class="row"><div><b>{{$c->favorite?'★ ':''}}{{$c->label}}</b><small>{{$c->project?->name ?? 'General'}} · {{$c->category?:'Sin categoría'}} @if($c->password_changed_at)· clave {{$c->password_changed_at->diffForHumans()}}@endif</small></div><span class="secret">••••••••••••</span><button class="reveal" data-url="{{route('credentials.reveal',$c)}}">Revelar</button><div><a href="{{route('credentials.edit',$c)}}">Editar</a> · <form style="display:inline" method="POST" action="{{route('credentials.favorite',$c)}}">@csrf<button class="reveal" type="submit">{{$c->favorite?'Quitar ★':'Favorita'}}</button></form></div></div>@empty<p class="muted">Aún no hay credenciales.</p>@endforelse</div>
<script>document.querySelectorAll('.reveal[data-url]').forEach(b=>b.onclick=async()=>{let r=await fetch(b.dataset.url,{method:'POST',headers:{'X-CSRF-TOKEN':'{{csrf_token()}}','Accept':'application/json'}});if(!r.ok)return;let d=await r.json(),row=b.closest('.row'),secret=row.querySelector('.secret');secret.textContent=(d.username?d.username+' / ':'')+d.password;b.textContent='Ocultar';setTimeout(()=>{secret.textContent='••••••••••••';b.textContent='Revelar'},15000)});</script>@endsection
